"""Build train.jsonl: hand-written synthetic phone-agent turns (tag: synthetic) for the two demo businesses.
Each row: biz, tag, history (list of role/content), user, assistant. Facts follow data/bakeoff/probe_systems.json only.
Run: python build_train.py   (writes train.jsonl next to this file)"""
import json, pathlib

A = lambda c: {"role": "assistant", "content": c}
R = []


def add(biz, tag, user, reply, hist=()):
    R.append({"biz": biz, "tag": tag, "history": list(hist), "user": user, "assistant": reply, "source": "synthetic"})


r = lambda *a, **k: add("rest", *a, **k)
c = lambda *a, **k: add("clinic", *a, **k)

